<?php
declare(strict_types=1);
putenv('SUPERAPP_DSN='.(getenv('SUPERAPP_TEST_DSN')?:'sqlite::memory:'));
putenv('SUPERAPP_DB_USER='.(getenv('SUPERAPP_TEST_DB_USER')?:''));
putenv('SUPERAPP_DB_PASS='.(getenv('SUPERAPP_TEST_DB_PASS')?:''));
putenv('SUPERAPP_DEMO=false');
require __DIR__.'/../app/bootstrap.php';
$checks=0;
function ok(bool $value,string $label):void{global $checks;if(!$value)throw new RuntimeException('FAILED: '.$label);echo 'ok '.(++$checks).' - '.$label."\n";}
function rejects(callable $fn,int $code,string $label):void{try{$fn();}catch(HttpError $e){ok($e->getCode()===$code,$label);return;}throw new RuntimeException('FAILED: '.$label);}
migrate();$prefix='ct'.bin2hex(random_bytes(4));$a=create_user(['username'=>$prefix.'a','email'=>$prefix.'a@example.invalid','password'=>'a community test passphrase']);$b=create_user(['username'=>$prefix.'b','email'=>$prefix.'b@example.invalid','password'=>'another community passphrase']);
$alice=one('SELECT * FROM users WHERE id=?',[$a]);$bob=one('SELECT * FROM users WHERE id=?',[$b]);
try {
    // Upgrade/re-run migrations must preserve previously stored content.
    $entry=save_entry($alice,['kind'=>'post','title'=>'Survives upgrade']);migrate();
    ok(one('SELECT title FROM entries WHERE id=?',[$entry])['title']==='Survives upgrade','migration rerun preserves content');
    $link=save_start_link($alice,['title'=>'NAS','target_url'=>'http://192.168.1.40/','position'=>'2']);
    ok($link>0,'private LAN shortcut accepted without fetching');
    rejects(fn()=>save_start_link($bob,['title'=>'stolen','target_url'=>'https://example.org'],$link),404,'shortcut edit ownership enforced');
    rejects(fn()=>save_start_link($alice,['title'=>'bad','target_url'=>'javascript:alert(1)']),422,'unsafe shortcut rejected');
    rejects(fn()=>save_start_link($alice,['title'=>'bad','target_url'=>'https://example.org','position'=>'-1']),422,'invalid shortcut order rejected');
    save_start_note($alice,['body'=>'private intention']);save_start_note($alice,['body'=>'updated intention']);
    ok(one('SELECT body FROM start_notes WHERE user_id=?',[$a])['body']==='updated intention','private note upsert works');
    $project=save_project($alice,['title'=>'NAS rebuild','summary'=>'A careful migration']);
    ok(one('SELECT visibility FROM projects WHERE id=?',[$project])['visibility']==='private','project defaults to private');
    rejects(fn()=>public_project($project,null),404,'private project hidden from anonymous');
    rejects(fn()=>public_project($project,$bob),404,'private project hidden from another member');
    ok(public_project($project,$alice)['title']==='NAS rebuild','owner can see private project');
    rejects(fn()=>save_project($bob,['title'=>'stolen'],$project),404,'cross-account project write rejected');
    rejects(fn()=>save_project($alice,['state'=>'nonsense'],$project),422,'invalid project state rejected');
    rejects(fn()=>save_project($alice,['visibility'=>'everyone'],$project),422,'invalid project visibility rejected');
    save_project($alice,['visibility'=>'unlisted'],$project);
    ok(public_project($project,null)['visibility']==='unlisted','unlisted project readable by direct address');
    $part=save_project_update($alice,$project,['kind'=>'part','title'=>'Memory','cost'=>'19.95']);
    ok((int)one('SELECT cost_cents FROM project_updates WHERE id=?',[$part])['cost_cents']===1995,'parts use exact integer cents');
    rejects(fn()=>save_project_update($bob,$project,['kind'=>'log','title'=>'stolen']),404,'cross-account project update rejected');
    rejects(fn()=>save_project_update($alice,$project,['kind'=>'part','title'=>'bad','cost'=>'1.001']),422,'fractional cents rejected');
    foreach(['-1','1e3','NaN','01','10000000.00'] as $amount)rejects(fn()=>cents($amount),422,'invalid or excessive amount rejected');
    $milestone=save_project_update($alice,$project,['kind'=>'milestone','title'=>'Migrate','completed'=>'1','cost'=>'99.99']);
    $m=one('SELECT * FROM project_updates WHERE id=?',[$milestone]);ok((int)$m['completed']===1&&(int)$m['cost_cents']===0,'milestone completes without adding parts cost');
    save_project_update($alice,$project,['kind'=>'milestone','title'=>'Migrate'], $milestone);
    ok((int)one('SELECT completed FROM project_updates WHERE id=?',[$milestone])['completed']===0,'milestone can be reopened');
    $other=save_project($alice,['title'=>'Other']);rejects(fn()=>save_project_update($alice,$other,['kind'=>'log','title'=>'move'],$part),404,'updates cannot be moved between projects');
    $ring=save_ring($alice,['name'=>'Linux neighbours','description'=>'Small boxes, big ideas']);
    ok(count(ring_people($ring))===1,'ring owner starts as approved member');
    rejects(fn()=>manage_ring($bob,$ring),403,'non-owner cannot manage ring');
    rejects(fn()=>join_ring($bob,$ring,['website'=>'javascript:bad']),422,'unsafe ring destination rejected');
    join_ring($bob,$ring,['website'=>'https://example.org/']);
    ok(count(ring_people($ring))===1,'pending membership excluded');
    rejects(fn()=>join_ring($bob,$ring,[]),422,'duplicate membership rejected');
    $member=(int)one('SELECT id FROM ring_members WHERE ring_id=? AND user_id=?',[$ring,$b])['id'];
    query("UPDATE ring_members SET status='approved' WHERE id=?",[$member]);$people=ring_people($ring);$ownerMember=(int)$people[0]['id'];
    ok(count($people)===2,'approved membership becomes navigable');
    foreach(['next','previous','random'] as $direction)ok((int)ring_destination($ring,$ownerMember,$direction)['id']===$member,$direction.' chooses the other approved member');
    ok((int)ring_destination($ring,$member,'next')['id']===$ownerMember,'ring navigation wraps');
    rejects(fn()=>ring_destination($ring,999999,'next'),404,'unknown origin member rejected');
    rejects(fn()=>ring_destination($ring,$member,'evil'),422,'unknown ring direction rejected');
    query('UPDATE users SET listed=0 WHERE id=?',[$b]);ok(count(ring_people($ring))===1,'discovery opt-out hides ring membership');
    rejects(fn()=>ring_destination($ring,$ownerMember,'next'),422,'single-member ring has explicit navigation limit');
    query('UPDATE users SET listed=1,suspended=1 WHERE id=?',[$b]);ok(count(ring_people($ring))===1,'suspended member excluded');
    query('UPDATE users SET suspended=0 WHERE id=?',[$b]);
    $data=['name'=>'Example lead','website'=>'https://example.org','claim'=>'Canadian-owned','evidence_url'=>'https://example.org/about','alternatives'=>'BigCloud','ownership_description'=>'Owner describes Canadian headquarters; incorporation not checked.','ownership_source'=>'https://example.org/about','ownership_date'=>'2025-01-01'];
    submit_directory($alice,$data);$directory=(int)db()->lastInsertId();$directory=(int)one('SELECT id FROM directory WHERE user_id=?',[$a])['id'];
    ok(count(rows('SELECT * FROM directory_facts WHERE directory_id=?',[$directory]))===1,'only documented dimensions are stored');
    ok(one('SELECT alternatives FROM directory_details WHERE directory_id=?',[$directory])['alternatives']==='BigCloud','alternative label persisted');
    $bad=$data;$bad['ownership_source']='';rejects(fn()=>submit_directory($alice,$bad),422,'claim requires its own source');
    $bad=$data;$bad['ownership_date']='2025-02-30';rejects(fn()=>submit_directory($alice,$bad),422,'impossible source-check date rejected');
    $bad=$data;$bad['ownership_date']='2999-01-01';rejects(fn()=>submit_directory($alice,$bad),422,'future source-check date rejected');
    ok((int)one('SELECT COUNT(*) AS n FROM directory WHERE user_id=?',[$a])['n']===1,'invalid evidence does not create partial listing');
    rejects(fn()=>directory_correction($bob,$directory,['body'=>'Update','evidence_url'=>'https://example.org/new']),404,'pending listings cannot receive public corrections');
    query("UPDATE directory SET status='approved' WHERE id=?",[$directory]);directory_correction($bob,$directory,['body'=>'Changed owner','evidence_url'=>'https://example.org/new']);
    ok(one('SELECT status FROM directory_corrections WHERE directory_id=?',[$directory])['status']==='open','corrections queue for review');
    $report=['month'=>'2099-01','hosting'=>'10.25','backups'=>'1.10','other'=>'0','contributions'=>'8.05'];
    rejects(fn()=>save_funding($alice,$report),403,'member cannot publish financial figures');
    $admin=array_replace($alice,['role'=>'admin']);rejects(fn()=>save_funding($admin,$report),422,'future report rejected');
    // Dedicated historical fixture month. Restore any existing fixture to keep disposable DB reruns clean.
    $month='2000-01';$previous=one('SELECT * FROM funding_reports WHERE month=?',[$month]);
    $report['month']=$month;save_funding($admin,$report);$record=one('SELECT * FROM funding_reports WHERE month=?',[$month]);
    ok((int)$record['hosting_cents']===1025&&(int)$record['contributions_cents']===805,'monthly funding preserves exact cents');
    $report['contributions']='12.34';save_funding($admin,$report);ok((int)one('SELECT contributions_cents FROM funding_reports WHERE month=?',[$month])['contributions_cents']===1234,'report can be corrected without duplication');
    query('DELETE FROM funding_reports WHERE month=?',[$month]);if($previous)query('INSERT INTO funding_reports (month,hosting_cents,backups_cents,other_cents,contributions_cents,notes,updated_at) VALUES (?,?,?,?,?,?,?)',array_values($previous));
    $export=export_account($alice);ok($export['start_page']['note']==='updated intention','private note exported');
    ok(count($export['projects'])===2&&count($export['projects'][0]['updates'])===2,'projects and nested updates exported');
    ok(count($export['webrings_owned'])===1&&count($export['webring_memberships'])===1,'ring ownership and membership exported');
    ok(count($export['directory_evidence'])===1&&count($export['directory_alternatives'])===1,'directory sources and alternatives exported');
    ok(count(export_account($bob)['directory_corrections'])===1,'authored corrections exported');
    query('UPDATE users SET suspended=1 WHERE id=?',[$a]);rejects(fn()=>public_project($project,null),404,'suspended project owner hidden');rejects(fn()=>ring_for($ring),404,'suspended ring owner hidden');
    query('DELETE FROM users WHERE id=?',[$a]);
    foreach(['start_links','start_notes','projects','rings'] as $table)ok((int)one('SELECT COUNT(*) AS n FROM '.$table.' WHERE user_id=?',[$a])['n']===0,$table.' cascade on account deletion');
    ok((int)one('SELECT COUNT(*) AS n FROM project_updates WHERE project_id=?',[$project])['n']===0,'project updates cascade');
    ok((int)one('SELECT COUNT(*) AS n FROM ring_members WHERE ring_id=?',[$ring])['n']===0,'ring members cascade');
    ok((int)one('SELECT COUNT(*) AS n FROM directory_facts WHERE directory_id=?',[$directory])['n']===0,'directory facts cascade');
    ok((int)one('SELECT COUNT(*) AS n FROM directory_corrections WHERE directory_id=?',[$directory])['n']===0,'directory corrections cascade');
    echo "PASS: {$checks} community checks on ".db()->getAttribute(PDO::ATTR_DRIVER_NAME)."\n";
} finally {query('DELETE FROM users WHERE id IN (?,?)',[$a,$b]);}
